/* ===================== BÀI 39 · Bank chẵn/lẻ và A0/BHE ===================== */
/* Bài 39 · Bank chẵn/lẻ và A0/BHE (AMTS-EMB-002-M10-L03, X86-039) — sinh bởi tools/author/mpu8086/l39.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P39=[{"label": "Ví dụ: byte chẵn và byte lẻ, một dải mỗi lần", "code": "; Byte ở địa chỉ chẵn và byte ở địa chỉ lẻ: mỗi lần\n; đọc là một chu kỳ bus, chỉ một dải hoạt động\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nb0      DB      11H                     ; độ lệch 0 (chẵn): dải chẵn, D7–D0\nb1      DB      22H                     ; độ lệch 1 (lẻ): dải lẻ, D15–D8\nkq      DW      ?                       ; độ lệch 2 (chẵn)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, b1                  ; byte lẻ: BHE = 0, A0 = 1\n        MOV     AH, AL\n        MOV     AL, b0                  ; byte chẵn: BHE = 1, A0 = 0\n        MOV     kq, AX                  ; word chẵn: BHE = 0, A0 = 0\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai byte ở hai địa chỉ liền nhau: b1 (lẻ) đi trên D15–D8 với BHE = 0, A0 = 1; b0 (chẵn) đi trên D7–D0 với BHE = 1, A0 = 0. Cả hai lệnh MOV AL, … đều 10 chu kỳ: byte lẻ không bị phạt. MOV kq, AX ghi word chẵn trong 1 chu kỳ bus. Xem Công cụ 39.1, mẫu đầu. Đoán trước: kq bằng bao nhiêu? Đáp án 2211h (byte thấp 11h ở kq, byte cao 22h)."}, {"label": "Ví dụ: word ở địa chỉ chẵn, một chu kỳ bus", "code": "; Word ở địa chỉ chẵn: hai dải cùng hoạt động,\n; 16 bit đi trong MỘT chu kỳ bus\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nw0      DW      3344H                   ; độ lệch 0 (chẵn)\nw1      DW      ?                       ; độ lệch 2 (chẵn)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, w0                  ; 1 chu kỳ bus đọc\n        ADD     AX, 1111H\n        MOV     w1, AX                  ; 1 chu kỳ bus ghi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "w0 ở độ lệch 0, w1 ở độ lệch 2: đều chẵn nên mỗi lần đọc/ghi word là 1 chu kỳ bus, MOV AX, w0 và MOV w1, AX đều 10 chu kỳ. Đoán trước: sau ADD, AX bằng bao nhiêu? Đáp án 4455h."}, {"label": "Bẫy: word ở địa chỉ lẻ tốn thêm chu kỳ", "code": "; Word ở địa chỉ lẻ: 8086 tách thành 2 chu kỳ bus,\n; mỗi lần truy cập tốn thêm 4 chu kỳ xung nhịp\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DB      0                       ; độ lệch 0\nwl      DW      5566H                   ; độ lệch 1 (lẻ)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, wl                  ; đọc word lẻ: 2 chu kỳ bus\n        ADD     wl, 1                   ; đọc + ghi word lẻ: 4 chu kỳ bus\n        MOV     AX, wl\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: dem chiếm độ lệch 0 nên wl ở độ lệch 1 (lẻ). MOV AX, wl tốn 10 + 4 = 14 chu kỳ; ADD wl, 1 đọc rồi ghi word lẻ: 17 + 6 + 4 + 4 = 31 chu kỳ, 4 chu kỳ bus. Kết quả vẫn đúng (wl = 5567h), chỉ chậm hơn. So với Ví dụ 4. Đoán trước: ADD wl, 1 tốn bao nhiêu chu kỳ? Đáp án 31."}, {"label": "Ví dụ: EVEN đưa word về địa chỉ chẵn", "code": "; Cùng chương trình nhưng thêm EVEN: trình dịch chèn\n; 1 byte trống để wl bắt đầu ở địa chỉ chẵn\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DB      0                       ; độ lệch 0\n        EVEN                            ; chèn 1 byte, độ lệch thành 2\nwl      DW      5566H                   ; độ lệch 2 (chẵn)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, wl                  ; 1 chu kỳ bus\n        ADD     wl, 1                   ; 2 chu kỳ bus\n        MOV     AX, wl\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "EVEN chèn 1 byte trống sau dem nên wl dời tới độ lệch 2: xem mã máy A1 02 00 thay vì A1 01 00. Cùng ba lệnh nhưng 10 + 23 + 10 = 43 chu kỳ, ít hơn Ví dụ 3 là 16. Đoán trước: MOV AX, wl lần đầu tốn bao nhiêu chu kỳ? Đáp án 10."}, {"label": "Ví dụ: dải nhớ và địa chỉ trong chip", "code": "; Địa chỉ 12345h trên hai chip 8 bit: A0 chọn dải,\n; A19–A1 thành địa chỉ trong chip (dịch phải 1 bit)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nadrLo   DW      2345H                   ; A15–A0\nadrHi   DB      01H                     ; A19–A16\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, adrLo\n        MOV     DL, adrHi\n        XOR     DH, DH                  ; DX:AX = 0001:2345\n        MOV     BL, 'E'                 ; E: dải chẵn\n        TEST    AL, 1                   ; A0\n        JZ      chan\n        MOV     BL, 'O'                 ; O: dải lẻ\nchan:\n        SHR     DX, 1                   ; dịch cả DX:AX sang phải 1 bit\n        RCR     AX, 1                   ; bit 0 của DX đi vào bit 15 của AX\n        PUSH    AX\n        PUSH    DX\n        MOV     DL, BL\n        MOV     AH, 02H\n        INT     21H                     ; in E hoặc O\n        MOV     DL, ' '\n        INT     21H\n        POP     AX                      ; AL = phần cao (A19–A17 → 3 bit)\n        CALL    inNib\n        POP     BX                      ; phần thấp\n        CALL    inHex4\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ninHex4  PROC                            ; in BX ra 4 chữ số hex\n        MOV     CH, 4\nlap4:\n        MOV     CL, 4\n        ROL     BX, CL\n        MOV     AL, BL\n        CALL    inNib\n        DEC     CH\n        JNZ     lap4\n        RET\ninHex4  ENDP\n\ninNib   PROC                            ; in 4 bit thấp của AL (0–F)\n        AND     AL, 0FH\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     inNib1\n        ADD     AL, 7\ninNib1:\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninNib   ENDP\n        END     MAIN\n", "input": "", "note": "Địa chỉ 12345h có A0 = 1 nên nằm ở dải lẻ (O). Địa chỉ trong chip = 12345h dịch phải 1 bit = 091A2h: SHR DX, 1 đẩy bit 0 của DX vào CF, RCR AX, 1 đưa CF vào bit 15 của AX. Màn hình O 091A2. Đoán trước: sau RCR AX, 1, AX bằng bao nhiêu? Đáp án 91A2h."}, {"label": "Lỗi: SP lẻ làm chậm PUSH và POP", "code": "; SP lẻ: mỗi PUSH/POP thành word ở địa chỉ lẻ,\n; 2 chu kỳ bus và thêm 4 chu kỳ xung nhịp\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1234H\n        PUSH    AX                      ; SP chẵn: 11 chu kỳ\n        POP     BX                      ; 8 chu kỳ\n        DEC     SP                      ; lỗi: SP thành số lẻ\n        PUSH    AX                      ; 11 + 4 chu kỳ\n        POP     BX                      ; 8 + 4 chu kỳ\n        INC     SP                      ; trả SP về như cũ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: DEC SP làm SP lẻ. PUSH AX cất word ở địa chỉ lẻ: 11 + 4 = 15 chu kỳ, POP BX 8 + 4 = 12, so với 11 và 8 khi SP chẵn. Dữ liệu vẫn đúng (BX = 1234h) nhưng mọi CALL, RET, PUSH, POP, INT sau đó đều chậm. Sửa: bỏ DEC SP, giữ SP chẵn. Đoán trước: PUSH AX lần hai tốn bao nhiêu chu kỳ? Đáp án 15."}];
