makeX86Ex(document.getElementById("ex-l39"),sim39,[{"t": "BHE và A0 của từng chu kỳ bus", "d": "Đọc hai phím bằng INT 21h hàm 08h: B (truy cập byte) hoặc W (word), rồi chữ số hex cuối của địa chỉ (0–9, A–F in hoa; chỉ cần biết A0). In cặp BHE A0 của từng chu kỳ bus mà 8086 dùng, cách nhau một dấu cách (ví dụ W5 → 01 10), và ghi số chu kỳ bus vào biến byte nck. Các chuỗi '10$', '01$', '00$' có sẵn trong .DATA. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: BHE và A0 của từng chu kỳ bus.\n; Đọc B (byte) hoặc W (word), rồi chữ số hex cuối của\n; địa chỉ. In cặp BHE A0 của mỗi chu kỳ bus, cách nhau\n; một dấu cách; ghi số chu kỳ bus vào nck.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nnck     DB      ?\ns10     DB      '10$'\ns01     DB      '01$'\ns00     DB      '00$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; B hoặc W\n        INT     21H\n        MOV     BH, AL\n        CALL    docHex                  ; chữ số hex cuối của địa chỉ\n; TODO: xét kiểu và A0, in kết quả, ghi nck\n        MOV     nck, 1\n        MOV     DX, OFFSET s00\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ndocHex  PROC                            ; đọc 1 chữ số hex vào AL (0–15)\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        CMP     AL, 9\n        JBE     docHex1\n        SUB     AL, 7\ndocHex1:\n        RET\ndocHex  ENDP\n        END     MAIN\n", "tests": [{"in": "W5", "out": "01 10", "mem": [{"at": "nck", "bytes": [2]}]}, {"in": "B4", "out": "10", "mem": [{"at": "nck", "bytes": [1]}]}, {"in": "B5", "out": "01", "mem": [{"at": "nck", "bytes": [1]}]}, {"in": "W4", "out": "00", "mem": [{"at": "nck", "bytes": [1]}]}, {"in": "WF", "out": "01 10", "mem": [{"at": "nck", "bytes": [2]}]}, {"in": "B0", "out": "10", "mem": [{"at": "nck", "bytes": [1]}]}, {"in": "WA", "out": "00", "mem": [{"at": "nck", "bytes": [1]}]}]}, {"t": "Dải nhớ và địa chỉ trong chip", "d": "Vùng 0000h–FFFFh của một bo được làm bằng hai chip 8 bit 32 KB: chip dải chẵn nối D7–D0, chip dải lẻ nối D15–D8; cả hai nhận A15–A1 của CPU làm địa chỉ A14–A0 của chip. Đọc địa chỉ 4 chữ số hex (thủ tục docHex có sẵn). In E nếu byte nằm ở chip dải chẵn, O nếu ở chip dải lẻ, một dấu cách, rồi địa chỉ trong chip ra 4 chữ số hex (ví dụ 1235 → O 091A); ghi địa chỉ trong chip vào biến word dc. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: hai chip 32 KB làm dải chẵn và dải lẻ\n; của vùng 0000h–FFFFh. Đọc địa chỉ 4 chữ số hex,\n; in E (dải chẵn) hoặc O (dải lẻ), dấu cách, rồi địa\n; chỉ trong chip 4 chữ số hex; ghi nó vào dc.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndc      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n; TODO: đọc 4 chữ số vào SI, xét A0, tính dc\n        MOV     dc, 0\n        MOV     DL, 'E'\n        MOV     AH, 02H\n        INT     21H\n        MOV     DL, ' '\n        INT     21H\n        MOV     BX, dc\n        CALL    inHex4\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n\ndocHex  PROC                            ; đọc 1 chữ số hex vào AL (0–15)\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        CMP     AL, 9\n        JBE     docHex1\n        SUB     AL, 7\ndocHex1:\n        RET\ndocHex  ENDP\n\ninHex4  PROC                            ; in BX ra 4 chữ số hex\n        MOV     CH, 4\nlap4:\n        MOV     CL, 4\n        ROL     BX, CL\n        MOV     AL, BL\n        CALL    inNib\n        DEC     CH\n        JNZ     lap4\n        RET\ninHex4  ENDP\n\ninNib   PROC                            ; in 4 bit thấp của AL (0–F)\n        AND     AL, 0FH\n        ADD     AL, '0'\n        CMP     AL, '9'\n        JBE     inNib1\n        ADD     AL, 7\ninNib1:\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        RET\ninNib   ENDP\n        END     MAIN\n", "tests": [{"in": "1235", "out": "O 091A", "mem": [{"at": "dc", "word": 2330}]}, {"in": "0000", "out": "E 0000", "mem": [{"at": "dc", "word": 0}]}, {"in": "0001", "out": "O 0000", "mem": [{"at": "dc", "word": 0}]}, {"in": "1234", "out": "E 091A", "mem": [{"at": "dc", "word": 2330}]}, {"in": "FFFF", "out": "O 7FFF", "mem": [{"at": "dc", "word": 32767}]}, {"in": "FFFE", "out": "E 7FFF", "mem": [{"at": "dc", "word": 32767}]}, {"in": "ABCD", "out": "O 55E6", "mem": [{"at": "dc", "word": 21990}]}]}, {"t": "Cộng mảng word nhanh hơn nhờ căn chỉnh", "d": "Đọc n (một chữ số '0'–'9') bằng INT 21h hàm 08h, ghi tổng n word đầu của mang vào biến word tong. Code mẫu đúng nhưng mang và tong nằm ở địa chỉ lẻ và tổng được cộng thẳng vào ô nhớ. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Được sắp xếp lại .DATA (giữ nguyên tên biến và giá trị của mang). Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: tổng n word đầu của mang (n = '0'–'9')\n; ghi vào tong. Bản này đúng nhưng chậm: mang và tong\n; nằm ở địa chỉ lẻ, tổng cộng thẳng vào ô nhớ.\n; Được sắp xếp lại .DATA (giữ tên và giá trị).\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndem     DB      ?\nmang    DW      0101H, 0202H, 0303H, 0404H, 0505H\n        DW      0606H, 0707H, 0808H, 0909H\ntong    DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     dem, AL\n        MOV     tong, 0\n        XOR     SI, SI\n        MOV     CL, dem\n        XOR     CH, CH\n        JCXZ    xong\nlap:\n        MOV     AX, mang[SI]\n        ADD     tong, AX\n        ADD     SI, 2\n        LOOP    lap\nxong:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "9", "mem": [{"at": "tong", "word": 11565}]}, {"in": "0", "mem": [{"at": "tong", "word": 0}]}, {"in": "1", "mem": [{"at": "tong", "word": 257}]}, {"in": "5", "mem": [{"at": "tong", "word": 3855}]}, {"in": "3", "mem": [{"at": "tong", "word": 1542}]}, {"in": "7", "mem": [{"at": "tong", "word": 7196}]}, {"in": "8", "mem": [{"at": "tong", "word": 9252}]}], "perf": {"cycles": 450, "bytes": 40}}]);
makeX86Bank(document.getElementById("bank-l39"),{"presets": [{"label": "Byte, word ở địa chỉ chẵn và lẻ", "note": "Bốn lần đọc ở vùng dữ liệu bắt đầu 01000h (địa chỉ giả định), giống Ví dụ 1–3.", "acc": [{"ins": "MOV AL, b1", "size": 1, "addr": 4097}, {"ins": "MOV AL, b0", "size": 1, "addr": 4096}, {"ins": "MOV AX, w0", "size": 2, "addr": 4098}, {"ins": "MOV AX, wl", "size": 2, "addr": 4101}]}, {"label": "ADD wl, 1 với wl ở địa chỉ lẻ", "note": "ADD bộ nhớ đọc rồi ghi lại cùng word; word ở địa chỉ lẻ (01005h, giả định) nên mỗi lần là 2 chu kỳ bus.", "acc": [{"ins": "ADD wl, 1 (đọc)", "size": 2, "addr": 4101}, {"ins": "ADD wl, 1 (ghi)", "size": 2, "addr": 4101, "rw": "w"}]}, {"label": "PUSH với SP chẵn và SP lẻ", "note": "PUSH ghi một word vào SS:SP − 2 (SS × 16 = 02000h, giả định). SP lẻ làm mọi PUSH/POP thành 2 chu kỳ bus.", "acc": [{"ins": "PUSH AX (SP = 0100h)", "size": 2, "addr": 8446, "rw": "w"}, {"ins": "PUSH AX (SP = 00FFh)", "size": 2, "addr": 8445, "rw": "w"}]}, {"label": "Reset vector trên hai EPROM 8 bit", "note": "8086 nạp lệnh theo word ở địa chỉ chẵn. Năm byte EA 00 00 00 F8 ở FFFF0h–FFFF4h nằm xen kẽ: byte ở địa chỉ chẵn trong EPROM dải chẵn, byte lẻ trong EPROM dải lẻ.", "acc": [{"ins": "nạp lệnh FFFF0h", "size": 2, "addr": 1048560}, {"ins": "nạp lệnh FFFF2h", "size": 2, "addr": 1048562}, {"ins": "nạp lệnh FFFF4h", "size": 2, "addr": 1048564}]}]});

makeQuiz("quiz39","score39",[{"q": "Lệnh <code>MOV AL, [BX]<\/code> với DS × 16 + BX = 01235h (địa chỉ lẻ). Chu kỳ bus đặt BHE, A0 thế nào và byte đi trên làn nào?", "o": ["BHE = 1, A0 = 0; byte đi trên D7–D0", "BHE = 0, A0 = 1; byte đi trên D15–D8", "BHE = 0, A0 = 0; cả D15–D0", "BHE = 1, A0 = 1; byte đi trên D7–D0"], "a": 1, "e": "Byte lẻ nằm ở dải lẻ, nối D15–D8, chọn bằng BHE = 0; A0 = 1 để dải chẵn không tham gia. CPU tự chuyển byte vào AL. Nhầm phổ biến: nghĩ AL luôn đi trên D7–D0."}, {"q": "Biến wl khai báo ngay sau một biến DB ở đầu đoạn dữ liệu (đoạn bắt đầu ở biên 16 byte). Lệnh sau tốn bao nhiêu chu kỳ (8086, không trạng thái chờ)?<pre class=\"mp-asm\">        MOV     AX, wl                  ; dạng A1 lo hi<\/pre>", "o": ["10 chu kỳ: MOV AX, bộ nhớ luôn 10", "14 chu kỳ: 10 + 4 vì wl ở địa chỉ lẻ", "18 chu kỳ: 10 + 8 vì đọc hai byte", "20 chu kỳ: gấp đôi vì hai chu kỳ bus"], "a": 1, "e": "wl ở độ lệch 1 (lẻ) nên word cần 2 chu kỳ bus; bảng thời gian cộng 4 cho mỗi lần truy cập word lẻ: 10 + 4 = 14 (Ví dụ 3). Cộng 8 chỉ đúng khi lệnh vừa đọc vừa ghi word lẻ."}, {"q": "<code>ADD wl, 1<\/code> với wl ở địa chỉ lẻ cần bao nhiêu chu kỳ bus dữ liệu?", "o": ["4: hai chu kỳ đọc rồi hai chu kỳ ghi", "2: một chu kỳ đọc, một chu kỳ ghi", "3: hai chu kỳ đọc, ghi gộp một lần", "1: CPU đọc và ghi trong cùng chu kỳ"], "a": 0, "e": "ADD bộ nhớ đọc word rồi ghi lại; mỗi lần truy cập word lẻ tách thành 2 chu kỳ bus (byte thấp ở địa chỉ lẻ, byte cao ở địa chỉ chẵn kế tiếp). Đáp án 2 đúng cho word chẵn."}, {"q": "Vùng 0000h–FFFFh làm bằng hai chip 32 KB (dải chẵn, dải lẻ). Byte ở địa chỉ F235h nằm ở chip nào, địa chỉ trong chip bao nhiêu?", "o": ["Chip dải chẵn, địa chỉ 791Ah", "Chip dải lẻ, địa chỉ F235h", "Chip dải lẻ, địa chỉ 791Bh", "Chip dải lẻ, địa chỉ 791Ah"], "a": 3, "e": "A0 = 1 nên ở dải lẻ; địa chỉ trong chip = F235h dịch phải 1 = 791Ah (A15–A1). Giữ nguyên F235h là quên rằng A0 của CPU không nối vào chip."}, {"q": "Một bo nối <span class=\"ov\">WE<\/span> của cả hai chip RAM trực tiếp với <span class=\"ov\">WR<\/span> (không dùng A0, BHE). Lệnh <code>MOV BYTE PTR [1000h], 41h<\/code> gây ra điều gì?", "o": ["Chỉ byte ở 1000h đổi, vì CPU chỉ đưa ra D7–D0", "Không có gì được ghi vì BHE = 1 cấm cả hai chip", "Byte ở 1001h cũng bị ghi đè bằng giá trị rác trên D15–D8", "Cả 1000h và 1001h cùng nhận đúng giá trị 41h"], "a": 2, "e": "Khi ghi byte chẵn, CPU chỉ đặt dữ liệu hợp lệ trên D7–D0; chip dải lẻ cũng nhận WE nên ghi giá trị không xác định trên D15–D8 vào 1001h. Ghi phải tách dải bằng A0 và BHE."}]);

